mapper.select:
SELECT r.*, v.name AS venueName, vs.date, vs.time_slot AS timeSlot, u.username AS userName FROM reservation r LEFT JOIN venue_schedule vs ON r.schedule_id = vs.id LEFT JOIN venue v ON r.venue_id = v.id LEFT JOIN sys_user u ON r.user_id = u.id
AND r.user_id = #{userId}
AND r.status = #{status}
ORDER BY r.create_time DESC
